INSERT INTO record (record_id, record_text, record_uuid) VALUES
(1, '스물한 살 때였어. 크리스마스이브 저녁 일곱 시에 시청 앞 트리 밑에서 만나기로 했지. 그때는 전화가 집집마다 있는 것도 아니라서 약속을 한 번 하면 무조건 지켜야 했어. 일곱 시가 한참 지났는데도 안 오더라. 눈은 펑펑 오고 발은 시리고. 그냥 갈까 하다가 트리를 한 바퀴 돌았는데, 그런데 반대편에 그 사람이 서 있더라. 군고구마 봉투를 꼭 안고서. 서로 반대편에서 한 시간을 기다린 거야.', '00000000-0000-4000-8000-000000000001'),
(2, '우리 국민학교 뒤에 큰 느티나무가 있었는데, 밤에 거기서 하얀 옷 입은 사람이 보인다는 소문이 돌았어. 아이들이 무서워서 그 길로 안 다녔지. 하루는 내가 용기를 내서 친구랑 가 봤는데, 글쎄 바람에 날리는 빨래였어. 그래도 그날 밤은 진짜 무서웠지.', '00000000-0000-4000-8000-000000000002'),
(3, '장날이었는데 우리 집 송아지가 없어진 거야. 아버지가 애지중지 키우던 송아지였는데. 온 동네 사람들이 같이 찾아다녔지. 발자국을 따라가 보니까 옆 동네 개울가까지 이어져 있더라고. 누가 데려간 건지, 스스로 간 건지 다들 한마디씩 했어.', '00000000-0000-4000-8000-000000000003'),
(4, '단오 때마다 마을 대항 씨름 대회가 열렸어. 우리 마을 대표가 덩치는 작은데 기술이 아주 좋았거든. 결승에서 자기보다 머리 하나는 큰 장사를 만났는데, 다들 졌다고 생각했지. 그런데 마지막에 번쩍 들어서 넘겨 버렸어. 그날 마을 잔치가 밤새 이어졌어.', '00000000-0000-4000-8000-000000000004'),
(5, '우리 할머니가 해 주시던 도깨비 이야기가 있어. 산 너머 고개에 도깨비가 살았는데, 밤에 지나가는 사람한테 씨름을 하자고 했대. 이기면 금방망이를 주고, 지면 밤새 고개를 못 넘게 했다지. 근데 도깨비는 메밀묵을 좋아해서, 메밀묵을 주면 그냥 보내 줬다고 하더라.', '00000000-0000-4000-8000-000000000005'),
(6, '열여섯 살에 처음으로 혼자 기차를 타고 서울에 왔어. 서울역에 내렸는데 사람이 어찌나 많은지 정신이 하나도 없더라. 주소 적은 쪽지 하나 들고 큰집을 찾아가야 했는데, 버스를 잘못 타서 한참을 헤맸지. 그때 처음 본 전차랑 높은 건물이 아직도 눈에 선해.', '00000000-0000-4000-8000-000000000006')
INSERT INTO story (story_id, story_title, story_category, story_background, story_summary, story_character, story_event, story_prologue, image_url, story_status, record_id) VALUES
(1, '비 오는 날의 첫사랑', 'ROMANCE', '1972년, 시골 마을의 중학교. 휴대전화가 없던 시절, 학생들은 손편지와 쪽지로 마음을 전하고 학교 뒤편 느티나무 아래에서 만나곤 했다.', '좋아하는 친구에게 마음을 전하지 못하는 영철이와 그의 가장 친한 친구가 함께 만들어가는 풋풋한 첫사랑 이야기', '좋아하는 친구에게 고백하고 싶은 영철이, 영철이가 좋아하는 같은 반 여학생 / 내 역할: 영철이의 가장 친한 친구', '같은 반 여학생을 남몰래 좋아하던 영철이는 비 오는 날 자신의 우산을 건네며 작은 쪽지를 남긴다. 하지만 직접 마음을 고백할 용기가 나지 않아 가장 친한 친구인 아이에게 고민을 털어놓는다. 아이가 건네는 말과 행동에 따라 영철이의 첫사랑에 새로운 사건들이 펼쳐진다.', '쉬는 시간, 영철이가 네 책상에 작은 쪽지를 올려놓았어. "좋아하는 애한테 이걸 전하고 싶은데, 용기가 안 나." 너는 영철이에게 뭐라고 말해줄 거야?', 'https://i.ibb.co/rGHNBBrW/image.png', 'PUBLISHED', 1),
(2, '느티나무 아래 하얀 그림자', 'HORROR', '산골 마을 국민학교 뒤편의 오래된 느티나무. 해가 지면 나무 아래에 하얀 그림자가 나타난다는 소문 때문에 아이들은 그 길을 피해 다닌다.', '용기를 낸 아이들이 느티나무 아래 하얀 그림자의 정체를 밝혀내는 이야기', '겁 많은 단짝 친구 복남, 소문을 퍼뜨린 6학년 형 / 내 역할: 그림자의 정체를 확인하러 가는 아이', '해 질 무렵 느티나무 아래에서 하얀 그림자가 흔들리는 것을 본 아이들이 모두 도망친다. 다음 날 주인공은 친구 복남과 함께 손전등을 들고 다시 느티나무로 향한다.', '해가 지자 느티나무 쪽에서 무언가 하얗게 펄럭였어. 복남이가 네 소매를 꽉 잡으며 물었어. "정말 가 볼 거야?" 너는 무엇을 챙겨서 어떻게 다가갈래?', 'https://i.ibb.co/pvxwY2Rn/image.png', 'PUBLISHED', 2),
(3, '장날에 사라진 송아지', 'THRILLER', '오일장이 열려 북적이는 시골 마을. 장에 간 사이 마을에서 가장 아끼던 송아지가 외양간에서 감쪽같이 사라졌다.', '발자국과 마을 사람들의 말을 단서로 사라진 송아지의 행방을 추리하는 이야기', '송아지 주인 김씨 아저씨, 장터 엿장수, 옆 동네 개울가의 소년 / 내 역할: 단서를 모으는 꼬마 탐정', '장날 오후, 김씨 아저씨네 송아지가 사라진다. 외양간 문은 열려 있고 진흙 위에 작은 발자국과 큰 발자국이 섞여 있다. 아이는 발자국을 따라 옆 동네 개울가까지 가며 마을 사람들에게 그날의 이야기를 묻는다.', '외양간 문이 활짝 열려 있었어. 진흙 바닥에는 송아지 발자국과 사람 발자국이 뒤섞여 있었지. 너는 어떤 단서부터 살펴볼래? 왜 그렇게 생각해?', 'https://i.ibb.co/mVrd5Z81/image.png', 'PUBLISHED', 3),
(4, '단오 씨름판의 작은 장사', 'ACTION', '단오날 모래판이 차려진 마을 공터. 이웃 마을들이 모여 마을 대항 씨름 대회를 연다.', '덩치는 작지만 기술이 뛰어난 마을 대표가 거대한 장사를 꺾고 우승하는 이야기', '작은 장사 덕배, 이웃 마을의 거구 장사 만석, 덕배의 씨름 스승 / 내 역할: 덕배를 응원하며 작전을 돕는 아이', '결승전에 오른 덕배는 자기보다 머리 하나는 큰 장사 만석과 맞붙는다. 첫 판을 내준 덕배에게 아이가 다가가 만석의 약점을 귀띔해 준다.', '"첫 판은 졌어." 모래를 털며 덕배 형이 숨을 몰아쉬었어. 맞은편에서는 만석이가 여유롭게 웃고 있었지. 너는 덕배 형에게 어떤 작전을 알려 줄래?', 'https://i.ibb.co/Jjs68Lx0/image.png', 'PUBLISHED', 4),
(5, '메밀묵 고개의 도깨비', 'FANTASY', '달빛만 비추는 산 너머 고개. 밤마다 도깨비가 나타나 지나가는 사람에게 씨름을 하자고 한다.', '메밀묵을 좋아하는 도깨비와 지혜를 겨루어 고개를 무사히 넘는 이야기', '금방망이를 든 도깨비, 메밀묵을 파는 주막 할머니 / 내 역할: 밤길에 고개를 넘어야 하는 아이', '아픈 동생에게 약을 전하러 밤에 고개를 넘던 아이 앞에 도깨비가 나타난다. 도깨비는 씨름에서 이기면 금방망이를 주고, 지면 아침까지 고개를 못 넘게 하겠다고 한다.', '달빛 아래 커다란 그림자가 길을 막았어. "씨름 한 판 하자! 지면 아침까지 못 지나가!" 도깨비가 껄껄 웃었지. 너는 이 도깨비를 어떻게 지나갈래?', 'https://i.ibb.co/2HNM801/image.png', 'PUBLISHED', 5),
(6, '처음 만난 서울역', 'ETC', '기차와 사람으로 가득한 옛 서울역. 전차가 다니고 높은 건물이 늘어선 낯선 도시.', '주소가 적힌 쪽지 한 장만 들고 처음 서울에 온 소녀가 큰집을 찾아가는 이야기', '처음 상경한 열여섯 살 소녀 말순, 친절한 전차 차장 / 내 역할: 말순에게 길을 알려 주는 서울 아이', '시골에서 혼자 기차를 타고 온 말순은 서울역 광장에서 길을 잃는다. 주소가 적힌 쪽지를 들고 버스를 탔지만 반대 방향으로 가 버리고, 아이가 말순을 발견한다.', '서울역 앞, 보따리를 든 언니가 쪽지를 내밀며 물었어. "이 주소로 가려면 어떻게 해야 하니?" 너는 언니에게 길을 어떻게 설명해 줄래?', 'https://i.ibb.co/Vcbd42Mh/image.png', 'PUBLISHED', 6)
INSERT INTO context (context_id, context_type, context_text, story_id) VALUES
(1, 'CHARACTER', '영호: 스물한 살 청년. 순희와 크리스마스이브 저녁 일곱 시에 트리 밑에서 만나기로 했다. 약속을 꼭 지키는 성격이라 한 시간째 같은 자리를 떠나지 못한다.', 1),
(2, 'CHARACTER', '순희: 영호와 약속한 사람. 영호에게 주려고 군고구마를 사 왔지만, 트리 반대편을 약속 장소로 알고 그곳에서 기다리고 있다.', 1),
(3, 'CHARACTER', '아이(나): 광장에서 눈사람을 만들던 동네 아이. 영호의 부탁을 받고 순희를 함께 찾아 나선다.', 1),
(4, 'EVENT', '약속 시간이 한 시간이나 지났는데도 두 사람은 만나지 못했다. 광장에는 사람이 많고 눈이 계속 내린다.', 1),
(5, 'EVENT', '트리 뒤편에서 종이봉투를 든 사람이 발견된다. 봉투 안에는 식은 군고구마 두 개가 들어 있다.', 1),
(6, 'EVENT', '두 사람이 서로 트리의 반대편을 약속 장소로 알고 있었다는 사실이 밝혀진다.', 1)
INSERT INTO chat (chat_id, chat_type, chat_text, story_id) VALUES
(1, 'STUDENT', '트리 뒤를 살펴밨어.', 1),
(2, 'FEEDBACK', '문장을 다시 써 볼까요?
